import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-javascript-title-case-string-manipulation":{"intro":"In this lab, we will explore how to convert a string into title case using JavaScript. We will use regular expressions to split the string into words and then capitalize the first letter of each word. By the end of this lab, you will have a better understanding of how to manipulate strings in JavaScript and apply this technique to format text in your web applications.","steps":[{"title":"Titlecase String","body":["Function to Convert String to Title Case","To convert a given string to title case, use the following function. It uses String.prototype.match() to break the string into words using an appropriate regular expression. Then it combines them using Array.prototype.map(), Array.prototype.slice(), Array.prototype.join(), and String.prototype.toUpperCase(). This capitalizes the first letter of each word and adds a whitespace between them.","Here are some examples of how to use the function:"],"code":[{"lang":"js","text":"const toTitleCase = (str) =>\n  str\n    .match(/[A-Z]{2,}(?=[A-Z][a-z]+[0-9]*|\\b)|[A-Z]?[a-z]+[0-9]*|[A-Z]|[0-9]+/g)\n    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))\n    .join(\" \");"},{"lang":"js","text":"toTitleCase(\"some_database_field_name\"); // 'Some Database Field Name'\ntoTitleCase(\"Some label that needs to be title-cased\");\n// 'Some Label That Needs To Be Title Cased'\ntoTitleCase(\"some-package-name\"); // 'Some Package Name'\ntoTitleCase(\"some-mixed_string with spaces_underscores-and-hyphens\");\n// 'Some Mixed String With Spaces Underscores And Hyphens'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"toTitleCase(\"some_database_field_name\"); // 'Some Database Field Name'\ntoTitleCase(\"Some label that needs to be title-cased\");\n// 'Some Label That Needs To Be Title Cased'\ntoTitleCase(\"some-package-name\"); // 'Some Package Name'\ntoTitleCase(\"some-mixed_string with spaces_underscores-and-hyphens\");\n// 'Some Mixed String With Spaces Underscores And Hyphens'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-toggle-element-in-array":{"intro":"In this lab, we will explore how to toggle an element in an array using JavaScript. The toggleElement() function allows you to remove an element from an array if it's already included in it or add the element to the array if it's not already present. This lab will help you understand how to use the includes() and filter() methods in combination with the spread operator to efficiently toggle array elements.","steps":[{"title":"Toggle Element in Array","body":["How to Toggle an Element in an Array","To toggle an element in an array, follow these steps:","By following these steps, you can easily toggle an element in an array using JavaScript."],"code":[{"lang":"js","text":"const toggleElement = (arr, val) =>\n  arr.includes(val) ? arr.filter((el) => el !== val) : [...arr, val];\n\ntoggleElement([1, 2, 3], 2); // [1, 3]\ntoggleElement([1, 2, 3], 4); // [1, 2, 3, 4]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const toggleElement = (arr, val) =>\n  arr.includes(val) ? arr.filter((el) => el !== val) : [...arr, val];\n\ntoggleElement([1, 2, 3], 2); // [1, 3]\ntoggleElement([1, 2, 3], 4); // [1, 2, 3, 4]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-transforming-object-properties-with-javascri":{"intro":"In this lab, we will explore the transform function in JavaScript which allows us to apply a specified function against an accumulator and each key in an object. By using Object.keys() and Array.prototype.reduce(), we can easily iterate over each key in an object and perform the desired transformation. This lab will provide hands-on experience with this useful function and demonstrate its practical applications in JavaScript programming.","steps":[{"title":"Transform Object","body":["The transform function applies a specified function against an accumulator and each key in the object, from left to right. Here's how to use it:","• Use Object.keys() to iterate over each key in the object. • Use Array.prototype.reduce() to apply the specified function against the given accumulator."],"code":[{"lang":"js","text":"const transform = (obj, fn, acc) =>\n  Object.keys(obj).reduce((a, k) => fn(a, obj[k], k, obj), acc);"},{"lang":"js","text":"transform(\n  { a: 1, b: 2, c: 1 },\n  (r, v, k) => {\n    (r[v] || (r[v] = [])).push(k);\n    return r;\n  },\n  {}\n); // { '1': ['a', 'c'], '2': ['b'] }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"transform(\n  { a: 1, b: 2, c: 1 },\n  (r, v, k) => {\n    (r[v] || (r[v] = [])).push(k);\n    return r;\n  },\n  {}\n); // { '1': ['a', 'c'], '2': ['b'] }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-truncating-strings-in-javascript":{"intro":"In this lab, we will explore the concept of truncating strings in JavaScript. Truncating a string involves shortening the length of a given string up to a specified length. Through various exercises and examples, you will learn how to implement a function that truncates strings and appends ellipsis to the end of the truncated string.","steps":[{"title":"Truncate String","body":["Truncate a String in JavaScript","To truncate a string in JavaScript, you can use the truncateString function. This function takes two arguments: str (the string to be truncated) and num (the maximum length of the truncated string).","The truncateString function checks if the length of the str is greater than num. If it is, the function truncates the string to the desired length and appends '...' to the end. If not, it returns the original string.","Here's the code for the truncateString function:"],"code":[{"lang":"js","text":"const truncateString = (str, num) =>\n  str.length > num ? str.slice(0, num > 3 ? num - 3 : num) + \"...\" : str;"},{"lang":"js","text":"truncateString(\"boomerang\", 7); // 'boom...'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"truncateString(\"boomerang\", 7); // 'boom...'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-truncate-string-at-whitespace":{"intro":"In this lab, we will explore the concept of truncating a string at whitespace in JavaScript. We will learn how to limit the length of a string while preserving its readability by respecting whitespace. Through the implementation of String.prototype.slice() and String.prototype.lastIndexOf(), we will create a function that can truncate a string to a specified length with an optional ending.","steps":[{"title":"Truncate String at Whitespace","body":["How to Truncate a String at Whitespace in JavaScript","Here's a function that truncates a string up to a specified length while respecting whitespace whenever possible:","To use this function, pass in the string you want to truncate as the first argument, the maximum length as the second argument, and an optional ending string as the third argument. If the length of the string is less than or equal to the specified limit, the original string will be returned. Otherwise, the function will find the last space before the limit and truncate the string at that point, adding the ending string if specified."],"code":[{"lang":"js","text":"const truncateStringAtWhitespace = (str, lim, ending = \"...\") => {\n  if (str.length <= lim) return str;\n  const lastSpace = str.slice(0, lim - ending.length + 1).lastIndexOf(\" \");\n  return str.slice(0, lastSpace > 0 ? lastSpace : lim - ending.length) + ending;\n};"},{"lang":"js","text":"truncateStringAtWhitespace(\"short\", 10); // 'short'\ntruncateStringAtWhitespace(\"not so short\", 10); // 'not so...'\ntruncateStringAtWhitespace(\"trying a thing\", 10); // 'trying...'\ntruncateStringAtWhitespace(\"javascripting\", 10); // 'javascr...'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"truncateStringAtWhitespace(\"short\", 10); // 'short'\ntruncateStringAtWhitespace(\"not so short\", 10); // 'not so...'\ntruncateStringAtWhitespace(\"trying a thing\", 10); // 'trying...'\ntruncateStringAtWhitespace(\"javascripting\", 10); // 'javascr...'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-truth-check-collection":{"intro":"In this lab, we will dive into the world of JavaScript programming and explore various concepts and techniques used in web development. Through hands-on practice and exercises, you will learn how to write clean and efficient code, work with data structures, and create dynamic and interactive web pages. Whether you're a beginner or an experienced programmer, this lab will provide you with valuable skills and knowledge to take your coding abilities to the next level.","steps":[{"title":"Truth Check Collection","body":["Truth Check Collection Function","Here's a function that checks if a predicate function is truthy for all elements of a collection.","• Use Array.prototype.every() to check if each passed object has the specified property and if it returns a truthy value."],"code":[{"lang":"js","text":"const truthCheckCollection = (collection, pre) =>\n  collection.every((obj) => obj[pre]);"},{"lang":"js","text":"truthCheckCollection(\n  [\n    { user: \"Tinky-Winky\", sex: \"male\" },\n    { user: \"Dipsy\", sex: \"male\" }\n  ],\n  \"sex\"\n); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"truthCheckCollection(\n  [\n    { user: \"Tinky-Winky\", sex: \"male\" },\n    { user: \"Dipsy\", sex: \"male\" }\n  ],\n  \"sex\"\n); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-type-of-value":{"intro":"In this lab, we will explore the concept of data types in JavaScript. We will learn how to use the getType function to determine the native type of any given value, whether it is undefined, null, or an instance of a constructor. By the end of the lab, you will have a solid understanding of how to work with different data types in JavaScript.","steps":[{"title":"Type of Value","body":["To get the type of a value, use the following function:","• The function returns 'undefined' or 'null' if the value is undefined or null. • Otherwise, it returns the name of the constructor by using Object.prototype.constructor and Function.prototype.name."],"code":[{"lang":"js","text":"const getType = (v) => {\n  if (v === undefined) {\n    return \"undefined\";\n  }\n\n  if (v === null) {\n    return \"null\";\n  }\n\n  return v.constructor.name;\n};"},{"lang":"js","text":"getType(new Set([1, 2, 3])); // 'Set'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"getType(new Set([1, 2, 3])); // 'Set'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-unescape-html-characters-with-javascript":{"intro":"In this lab, we will explore how to unescape HTML characters using JavaScript. HTML escaping is a common technique used to encode special characters in HTML to prevent cross-site scripting attacks. However, sometimes we need to convert the escaped characters back to their original form. We will learn how to do this by creating a function that unescapes the most common HTML characters.","steps":[{"title":"Unescape HTML","body":["This function unescapes escaped HTML characters. To use it, follow these steps:","• Call the unescapeHTML function and pass it a string with escaped characters. • The function will return the unescaped string."],"code":[{"lang":"js","text":"const unescapeHTML = (str) =>\n  str.replace(\n    /&amp;|&lt;|&gt;|&#39;|&quot;/g,\n    (tag) =>\n      ({\n        \"&amp;\": \"&\",\n        \"&lt;\": \"<\",\n        \"&gt;\": \">\",\n        \"&#39;\": \"'\",\n        \"&quot;\": '\"'\n      })[tag] || tag\n  );"},{"lang":"js","text":"unescapeHTML(\"&lt;a href=&quot;#&quot;&gt;Me &amp; you&lt;/a&gt;\");\n// '<a href=\"#\">Me & you</a>'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"unescapeHTML(\"&lt;a href=&quot;#&quot;&gt;Me &amp; you&lt;/a&gt;\");\n// '<a href=\"#\">Me & you</a>'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-unflatten-nested-javascript-objects":{"intro":"In this lab, we will explore how to unflatten an object with paths for keys in JavaScript. We will use nested Array.prototype.reduce() and String.prototype.split() methods to split each key with a dot delimiter and add objects against the keys. By the end of this lab, you will have a solid understanding of how to efficiently convert a flat object to a nested one.","steps":[{"title":"Unflatten Object","body":["How to Unflatten an Object in JavaScript","To unflatten an object with paths for keys in JavaScript, follow these steps:","• Use nested Array.prototype.reduce() to convert the flat path to a leaf node.","• Use String.prototype.split() to split each key with a dot delimiter and Array.prototype.reduce() to add objects against the keys."],"code":[{"lang":"js","text":"const unflattenObject = (obj) =>\n  Object.keys(obj).reduce((res, k) => {\n    k.split(\".\").reduce(\n      (acc, e, i, keys) =>\n        acc[e] ||\n        (acc[e] = isNaN(Number(keys[i + 1]))\n          ? keys.length - 1 === i\n            ? obj[k]\n            : {}\n          : []),\n      res\n    );\n    return res;\n  }, {});"},{"lang":"js","text":"unflattenObject({ \"a.b.c\": 1, d: 1 }); // { a: { b: { c: 1 } }, d: 1 }\nunflattenObject({ \"a.b\": 1, \"a.c\": 2, d: 3 }); // { a: { b: 1, c: 2 }, d: 3 }\nunflattenObject({ \"a.b.0\": 8, d: 3 }); // { a: { b: [ 8 ] }, d: 3 }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"unflattenObject({ \"a.b.c\": 1, d: 1 }); // { a: { b: { c: 1 } }, d: 1 }\nunflattenObject({ \"a.b\": 1, \"a.c\": 2, d: 3 }); // { a: { b: 1, c: 2 }, d: 3 }\nunflattenObject({ \"a.b.0\": 8, d: 3 }); // { a: { b: [ 8 ] }, d: 3 }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-ungroup-array-elements":{"intro":"In this lab, we will explore how to ungroup elements in an array of arrays using JavaScript. We will use a combination of built-in JavaScript functions such as reduce, map, and forEach to extract individual arrays from a single array of arrays. By the end of this lab, you will have a solid understanding of how to manipulate arrays in JavaScript to achieve the desired output.","steps":[{"title":"Ungroup Array Elements","body":["How to Ungroup Array Elements in JavaScript","To ungroup the elements in an array produced by the zip function, you can create an array of arrays using the unzip function in JavaScript. Here's how:","Here's the code for the unzip function:","You can use the unzip function with the following examples:"],"code":[{"lang":"js","text":"const unzip = (arr) =>\n  arr.reduce(\n    (acc, val) => (val.forEach((v, i) => acc[i].push(v)), acc),\n    Array.from({\n      length: Math.max(...arr.map((x) => x.length))\n    }).map((x) => [])\n  );"},{"lang":"js","text":"unzip([\n  [\"a\", 1, true],\n  [\"b\", 2, false]\n]); // [['a', 'b'], [1, 2], [true, false]]\nunzip([\n  [\"a\", 1, true],\n  [\"b\", 2]\n]); // [['a', 'b'], [1, 2], [true]]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"unzip([\n  [\"a\", 1, true],\n  [\"b\", 2, false]\n]); // [['a', 'b'], [1, 2], [true, false]]\nunzip([\n  [\"a\", 1, true],\n  [\"b\", 2]\n]); // [['a', 'b'], [1, 2], [true]]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-unique-values-in-array":{"intro":"In this lab, we will dive into the concept of arrays in JavaScript and learn how to find unique values in an array using the Set object and spread operator. We will explore a simple and efficient approach to remove duplicates from an array and return only the unique elements. This lab is perfect for those looking to improve their understanding of arrays and data manipulation in JavaScript.","steps":[{"title":"Unique Values in Array","body":["How to Find Unique Values in Array with JavaScript","To find all unique values in an array, you can follow these steps in JavaScript:","• Create a Set from the given array to discard duplicated values. • Use the spread operator (...) to convert the Set back to an array.","Here's an example code snippet:"],"code":[{"lang":"js","text":"const getUniqueValues = (arr) => [...new Set(arr)];"},{"lang":"js","text":"getUniqueValues([1, 2, 2, 3, 4, 4, 5]); // [1, 2, 3, 4, 5]"}]}],"commands":[],"reference":[{"path":"reference.js","text":"getUniqueValues([1, 2, 2, 3, 4, 4, 5]); // [1, 2, 3, 4, 5]"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-unix-timestamp-from-date":{"intro":"In this lab, we will be exploring JavaScript and its various capabilities. The lab will cover topics such as data types, functions, loops, and conditional statements, providing a solid foundation for anyone looking to start their journey in JavaScript programming. Through practical examples and exercises, participants will gain hands-on experience and develop a deeper understanding of the language.","steps":[{"title":"Unix Timestamp From Date","body":["How to Get Unix Timestamp From Date in JavaScript","You can use the following steps to get the Unix timestamp from a Date object in JavaScript:","• Use Date.prototype.getTime() to get the timestamp in milliseconds. • Divide the timestamp by 1000 to get the timestamp in seconds. • Use Math.floor() to round the resulting timestamp to an integer. • If you omit the date argument, the current date will be used.","Here's an example code snippet:"],"code":[{"lang":"js","text":"const getTimestamp = (date = new Date()) => Math.floor(date.getTime() / 1000);"},{"lang":"js","text":"getTimestamp(); // 1602162242"}]}],"commands":[],"reference":[{"path":"reference.js","text":"getTimestamp(); // 1602162242"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-uppercase-object-keys":{"intro":"In this lab, we will explore how to convert all the keys of an object to uppercase in JavaScript. You will learn how to use Object.keys() and Array.prototype.reduce() to create a new object with all the keys converted to uppercase letters. This technique can be useful in various scenarios where you need to standardize the keys of an object for consistency and ease of use.","steps":[{"title":"Uppercase Object Keys","body":["How to Uppercase Object Keys in JavaScript","To convert all the keys of an object to upper case in JavaScript, follow these steps:","• Use Object.keys() to get an array of the object's keys. • Use Array.prototype.reduce() to map the array to an object. • Use String.prototype.toUpperCase() to uppercase the keys.","To test the function, you can call it like this:"],"code":[{"lang":"js","text":"const upperize = (obj) =>\n  Object.keys(obj).reduce((acc, k) => {\n    acc[k.toUpperCase()] = obj[k];\n    return acc;\n  }, {});"},{"lang":"js","text":"upperize({ Name: \"John\", Age: 22 }); // { NAME: 'John', AGE: 22 }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"upperize({ Name: \"John\", Age: 22 }); // { NAME: 'John', AGE: 22 }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-generating-unique-identifiers-in-javascript":{"intro":"In this lab, we will explore how to generate a UUID in a browser using JavaScript. A UUID (Universally Unique Identifier) is a 128-bit value used to identify resources in a system in a way that is both unique and universal. By the end of this lab, you will have a clear understanding of how to generate a compliant UUID that can be used in your web applications.","steps":[{"title":"Generate UUID (Browser)","body":["To generate a UUID compliant with [RFC4122](https://www.ietf.org/rfc/rfc4122.txt) version 4 in a browser, follow these steps:","• Call the UUIDGeneratorBrowser() function to generate a UUID. For example, UUIDGeneratorBrowser() would return '7982fcfe-5721-4632-bede-6000885be57d'."],"code":[{"lang":"js","text":"const UUIDGeneratorBrowser = () =>\n  ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, (c) =>\n    (\n      c ^\n      (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (c / 4)))\n    ).toString(16)\n  );"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const UUIDGeneratorBrowser = () =>\n  ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, (c) =>\n    (\n      c ^\n      (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (c / 4)))\n    ).toString(16)\n  );"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-generating-uuid-in-node-js":{"intro":"In this lab, we will learn how to generate a UUID in Node.js. UUIDs are unique identifiers that are commonly used in distributed systems to uniquely identify entities without requiring centralized coordination. We will use the crypto module in Node.js to generate a UUID that is compliant with RFC4122 version 4.","steps":[{"title":"Generate UUID (Node.js)","body":["To generate a UUID in Node.js, follow the steps below:","Here's an example code snippet to generate UUID in Node.js:","You can call the UUIDGeneratorNode() method to generate a UUID."],"code":[{"lang":"js","text":"const crypto = require(\"crypto\");\n\nconst UUIDGeneratorNode = () =>\n  ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, (c) =>\n    (c ^ (crypto.randomBytes(1)[0] & (15 >> (c / 4)))).toString(16)\n  );"},{"lang":"js","text":"UUIDGeneratorNode(); // '79c7c136-60ee-40a2-beb2-856f1feabefc'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"UUIDGeneratorNode(); // '79c7c136-60ee-40a2-beb2-856f1feabefc'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-validating-numbers-in-javascript":{"intro":"In this lab, we will explore a JavaScript function that checks whether a given value is a number. We will use the parseFloat() method to convert the value to a number and then validate it using Number.isNaN() and Number.isFinite(). We will also use coercion to check if the value is a number. By the end of this lab, you will have a better understanding of how to validate numbers in JavaScript.","steps":[{"title":"Validate Number","body":["To validate if a given input is a number, follow these steps:","Here's the code for the validateNumber function:","You can use the validateNumber function as follows:"],"code":[{"lang":"js","text":"const validateNumber = (input) => {\n  const num = parseFloat(input);\n  return !Number.isNaN(num) && Number.isFinite(num) && Number(input) == input;\n};"},{"lang":"js","text":"validateNumber(\"10\"); // true\nvalidateNumber(\"a\"); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"validateNumber(\"10\"); // true\nvalidateNumber(\"a\"); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-mapping-unique-array-values-to-object-keys":{"intro":"In this lab, we will explore the concept of creating an object with the unique values of an array as keys and their frequencies as the values. We will achieve this by making use of the Array.prototype.reduce() method to map unique values to an object's keys, adding to existing keys every time the same value is encountered. Through this lab, we will gain a deeper understanding of the reduce method and how it can be used to solve programming problems efficiently.","steps":[{"title":"Value Frequencies","body":["Instructions for Counting Value Frequencies","To count the frequency of values in an array, follow these steps:","• To use this function, call frequencies with the array as its argument. For example:","With these instructions, you can easily count the frequency of values in any given array."],"code":[{"lang":"js","text":"const frequencies = (arr) =>\n  arr.reduce((a, v) => {\n    a[v] = a[v] ? a[v] + 1 : 1;\n    return a;\n  }, {});"},{"lang":"js","text":"frequencies([\"a\", \"b\", \"a\", \"c\", \"a\", \"a\", \"b\"]); // { a: 4, b: 2, c: 1 }\nfrequencies([...\"ball\"]); // { b: 1, a: 1, l: 2 }"}]}],"commands":[],"reference":[{"path":"reference.js","text":"frequencies([\"a\", \"b\", \"a\", \"c\", \"a\", \"a\", \"b\"]); // { a: 4, b: 2, c: 1 }\nfrequencies([...\"ball\"]); // { b: 1, a: 1, l: 2 }"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-if-value-is-of-type":{"intro":"In this lab, we will explore a JavaScript function that checks whether a provided value is of a specified type. We will use the is() function, which leverages the constructor property and Array.prototype.includes() method to determine if the value is of the specified type. This lab will help you gain a better understanding of type checking in JavaScript.","steps":[{"title":"Check if Value Is of Type","body":["Function to Check if Value Is of Type","To check if a provided value is of a specified type, follow these steps:","• Ensure that the value is not undefined or null by using Array.prototype.includes(). • Use Object.prototype.constructor to compare the constructor property on the value with the specified type. • The function is() below performs these checks and returns true if the value is of the specified type, and false otherwise.","You can use is() to check if a value is of various types, such as Array, ArrayBuffer, Map, RegExp, Set, WeakMap, WeakSet, String, Number, and Boolean. For example:"],"code":[{"lang":"js","text":"const is = (type, val) => ![, null].includes(val) && val.constructor === type;"},{"lang":"js","text":"is(Array, [1]); // true\nis(Map, new Map()); // true\nis(String, \"\"); // true\nis(Number, 1); // true\nis(Boolean, true); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"is(Array, [1]); // true\nis(Map, new Map()); // true\nis(String, \"\"); // true\nis(Number, 1); // true\nis(Boolean, true); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-vector-angle-calculation-in-javascript":{"intro":"In this lab, we will explore the concept of vector angle and learn how to calculate the angle between two vectors using JavaScript. We will use various mathematical functions such as Math.pow(), Math.sqrt(), and Math.acos() to perform the necessary calculations and derive the desired result. Through this lab, we will gain a better understanding of vector operations and their practical applications.","steps":[{"title":"Vector Angle","body":["To calculate the angle (theta) between two vectors, follow these steps:","Here's an example code snippet:","This function takes two arrays (x and y) as arguments and returns the angle (in radians) between them."],"code":[{"lang":"js","text":"const vectorAngle = (x, y) => {\n  let mX = Math.sqrt(x.reduce((acc, n) => acc + Math.pow(n, 2), 0));\n  let mY = Math.sqrt(y.reduce((acc, n) => acc + Math.pow(n, 2), 0));\n  return Math.acos(x.reduce((acc, n, i) => acc + n * y[i], 0) / (mX * mY));\n};\n\nvectorAngle([3, 4], [4, 3]); // 0.283794109208328"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const vectorAngle = (x, y) => {\n  let mX = Math.sqrt(x.reduce((acc, n) => acc + Math.pow(n, 2), 0));\n  let mY = Math.sqrt(y.reduce((acc, n) => acc + Math.pow(n, 2), 0));\n  return Math.acos(x.reduce((acc, n, i) => acc + n * y[i], 0) / (mX * mY));\n};\n\nvectorAngle([3, 4], [4, 3]); // 0.283794109208328"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-calculating-euclidean-vector-distance-in-jav":{"intro":"In this lab, we will dive into the world of JavaScript programming and explore the concept of vector distance. The purpose of the lab is to help you understand how to use Array.prototype.reduce(), Math.pow(), and Math.sqrt() to calculate the Euclidean distance between two vectors. By the end of the lab, you will have gained practical experience in implementing this useful function in JavaScript.","steps":[{"title":"Vector Distance","body":["To calculate the distance between two vectors, follow these steps:","• Test the formula by entering two vectors in the following format: vectorDistance([10, 0, 5], [20, 0, 10]); • The output will be the distance between the two vectors: 11.180339887498949."],"code":[{"lang":"js","text":"const vectorDistance = (x, y) =>\n  Math.sqrt(x.reduce((acc, val, i) => acc + Math.pow(val - y[i], 2), 0));"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const vectorDistance = (x, y) =>\n  Math.sqrt(x.reduce((acc, val, i) => acc + Math.pow(val - y[i], 2), 0));"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-walk-through-object":{"intro":"In this lab, we will explore the concept of creating a generator function that walks through all the keys of a given object using recursion. The purpose of this lab is to provide a hands-on experience for learners to understand how to use yield and yield* expressions in combination with for...of loops and Object.keys() to iterate over object keys and their values. By the end of this lab, learners will have a practical understanding of how to recursively walk through an object and generate an array of keys representing the current path and the corresponding values.","steps":[{"title":"Walk Through Object","body":["To generate a list of all the keys of a given object, use the following steps:","• Define a generator function called walk that takes an object and an array of keys. Use recursion to walk through all the keys of the object.","• Inside the walk function, use a for...of loop and Object.keys() to iterate over the keys of the object.","• Use typeof to check if each value in the given object is itself an object. If the value is an object, use the yield* expression to recursively delegate to the same generator function, walk, appending the current key to the array of keys."],"code":[{"lang":"js","text":"const walkThrough = function* (obj) {\n  const walk = function* (x, previous = []) {\n    for (let key of Object.keys(x)) {\n      if (typeof x[key] === \"object\") yield* walk(x[key], [...previous, key]);\n      else yield [[...previous, key], x[key]];\n    }\n  };\n  yield* walk(obj);\n};"},{"lang":"js","text":"const obj = {\n  a: 10,\n  b: 20,\n  c: {\n    d: 10,\n    e: 20,\n    f: [30, 40]\n  },\n  g: [\n    {\n      h: 10,\n      i: 20\n    },\n    {\n      j: 30\n    },\n    40\n  ]\n};\n[...walkThrough(obj)];\n/*\n[\n  [['a'], 10],\n  [['b'], 20],\n  [['c', 'd'], 10],\n  [['c', 'e'], 20],\n  [['c', 'f', '0'], 30],\n  [['c', 'f', '1'], 40],\n  [['g', '0', 'h'], 10],\n  [['g', '0', 'i'], 20],\n  [['g', '1', 'j'], 30],\n  [['g', '2'], 40]\n]\n*/"}]}],"commands":[],"reference":[{"path":"reference.js","text":"const obj = {\n  a: 10,\n  b: 20,\n  c: {\n    d: 10,\n    e: 20,\n    f: [30, 40]\n  },\n  g: [\n    {\n      h: 10,\n      i: 20\n    },\n    {\n      j: 30\n    },\n    40\n  ]\n};\n[...walkThrough(obj)];\n/*\n[\n  [['a'], 10],\n  [['b'], 20],\n  [['c', 'd'], 10],\n  [['c', 'e'], 20],\n  [['c', 'f', '0'], 30],\n  [['c', 'f', '1'], 40],\n  [['g', '0', 'h'], 10],\n  [['g', '0', 'i'], 20],\n  [['g', '1', 'j'], 30],\n  [['g', '2'], 40]\n]\n*/"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-week-of-year":{"intro":"In this lab, we will explore how to calculate the zero-indexed week of the year that a given date corresponds to using JavaScript. We will use the Date constructor and several Date.prototype methods to obtain the first Monday of the year and calculate the number of weeks between the first Monday and the given date. This lab is designed to enhance your understanding of JavaScript date manipulation and calculation.","steps":[{"title":"Week of Year","body":["Obtaining the Week of Year from a Date in JavaScript","To obtain the zero-indexed week of the year that corresponds to a date in JavaScript, follow these steps:","• Create a weekOfYear function that takes a date parameter. • Use the Date constructor and Date.prototype.getFullYear() to get the first day of the year as a Date object. • Use Date.prototype.setDate(), Date.prototype.getDate() and Date.prototype.getDay() along with the modulo (%) operator to get the first Monday of the year. • Subtract the first Monday of the year from the given date and divide with the number of milliseconds in a week. • Use Math.round() to get the zero-indexed week of the year corresponding to the given date. • If the given date is before the first Monday of the year, -0 is returned.","To use the weekOfYear function, simply call it with a Date object as its parameter:"],"code":[{"lang":"js","text":"const weekOfYear = (date) => {\n  const startOfYear = new Date(date.getFullYear(), 0, 1);\n  startOfYear.setDate(startOfYear.getDate() + (startOfYear.getDay() % 7));\n  return Math.round((date - startOfYear) / (7 * 24 * 3600 * 1000));\n};"},{"lang":"js","text":"weekOfYear(new Date(\"2021-06-18\")); // 23"}]}],"commands":[],"reference":[{"path":"reference.js","text":"weekOfYear(new Date(\"2021-06-18\")); // 23"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-weighted-random-sampling-in-javascript":{"intro":"In this lab, we will explore a practical implementation of a weighted sample function in JavaScript. The function returns a random element from an array, with probabilities assigned to each element based on the provided weights. Through this lab, we will learn how to use Array methods such as reduce() and findIndex() along with Math.random() to generate the desired outcome.","steps":[{"title":"Weighted Sample","body":["How to Get a Weighted Sample from an Array in JavaScript","To randomly get an element from an array based on the provided weights, follow these steps:","Here is the code to achieve this:","You can test this function by passing an array and its corresponding weights as arguments:"],"code":[{"lang":"js","text":"const weightedSample = (arr, weights) => {\n  let roll = Math.random();\n  return arr[\n    weights\n      .reduce(\n        (acc, w, i) => (i === 0 ? [w] : [...acc, acc[acc.length - 1] + w]),\n        []\n      )\n      .findIndex((v, i, s) => roll >= (i === 0 ? 0 : s[i - 1]) && roll < v)\n  ];\n};"},{"lang":"js","text":"weightedSample([3, 7, 9, 11], [0.1, 0.2, 0.6, 0.1]); // 9"}]}],"commands":[],"reference":[{"path":"reference.js","text":"weightedSample([3, 7, 9, 11], [0.1, 0.2, 0.6, 0.1]); // 9"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-word-wrap-string":{"intro":"In this lab, we will be exploring the concept of string manipulation in JavaScript. Specifically, we will be focusing on the wordWrap function which allows us to wrap a string to a given number of characters using a string break character. By the end of this lab, you will have a better understanding of how to manipulate strings in JavaScript to achieve specific formatting requirements.","steps":[{"title":"Word Wrap String","body":["Instructions for Word Wrap String","This code wraps a string to a given number of characters using a string break character. To use it, follow these steps:","• Use String.prototype.replace() and a regular expression to insert a given break character at the nearest whitespace of max characters. • If you don't want to use the default value of '\\n' for the third argument, br, you can omit it and provide your own character.","And here are some examples of how to use it:"],"code":[{"lang":"js","text":"const wordWrap = (str, max, br = \"\\n\") =>\n  str.replace(\n    new RegExp(`(?![^\\\\n]{1,${max}}$)([^\\\\n]{1,${max}})\\\\s`, \"g\"),\n    \"$1\" + br\n  );"},{"lang":"js","text":"wordWrap(\n  \"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Fusce tempus.\",\n  32\n);\n// 'Lorem ipsum dolor sit amet,\\nconsectetur adipiscing elit.\\nFusce tempus.'\n\nwordWrap(\n  \"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Fusce tempus.\",\n  32,\n  \"\\r\\n\"\n);\n// 'Lorem ipsum dolor sit amet,\\r\\nconsectetur adipiscing elit.\\r\\nFusce tempus.'"}]}],"commands":[],"reference":[{"path":"reference.js","text":"wordWrap(\n  \"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Fusce tempus.\",\n  32\n);\n// 'Lorem ipsum dolor sit amet,\\nconsectetur adipiscing elit.\\nFusce tempus.'\n\nwordWrap(\n  \"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Fusce tempus.\",\n  32,\n  \"\\r\\n\"\n);\n// 'Lorem ipsum dolor sit amet,\\r\\nconsectetur adipiscing elit.\\r\\nFusce tempus.'"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-introductory-programming-lab":{"intro":"I'm sorry, but as an AI language model, I cannot confirm the existence of a specific programming lab content without additional information. Can you please provide me with the lab's name or any other relevant details?","steps":[{"title":"Logical Xor","body":[],"code":[{"lang":"js","text":"const xor = (a, b) => (a || b) && !(a && b);"},{"lang":"js","text":"xor(true, true); // false\nxor(true, false); // true\nxor(false, true); // true\nxor(false, false); // false"}]}],"commands":[],"reference":[{"path":"reference.js","text":"xor(true, true); // false\nxor(true, false); // true\nxor(false, true); // true\nxor(false, false); // false"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-javascript-check-yes-no-string":{"intro":"In this lab, we will explore a JavaScript code snippet designed to check if a string input represents a 'yes' or 'no' answer. The yesNo function uses regular expressions to test if the input matches 'y' or 'yes' for a true response, 'n' or 'no' for a false response, or a default value if none is provided. You will have the opportunity to test this function with different inputs and defaults, and gain a better understanding of how regular expressions can be used in JavaScript.","steps":[{"title":"Check Yes/No String","body":["Function to Check Yes/No String","• The function returns true if the string is 'y'/'yes' and false if the string is 'n'/'no'. • To set a default answer, omit the second argument def. By default, the function will return false. • The function uses RegExp.prototype.test() to check if the string matches 'y'/'yes' or 'n'/'no'."],"code":[{"lang":"js","text":"const yesNo = (val, def = false) =>\n  /^(y|yes)$/i.test(val) ? true : /^(n|no)$/i.test(val) ? false : def;"},{"lang":"js","text":"yesNo(\"Y\"); // true\nyesNo(\"yes\"); // true\nyesNo(\"No\"); // false\nyesNo(\"Foo\", true); // true"}]}],"commands":[],"reference":[{"path":"reference.js","text":"yesNo(\"Y\"); // true\nyesNo(\"yes\"); // true\nyesNo(\"No\"); // false\nyesNo(\"Foo\", true); // true"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
